<?php declare(strict_types=1);namespace App\Controllers;use App\Core\Auth;use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Core\Validator;use App\Core\View;abstract class Controller{protected string $layout='layouts/main';protected function view(string $l,array $e=[],?string $c=null):Response{return Response::html(View::render($l,$e,$c??$this->layout));}protected function redirect(string $k):Response{return Response::redirect($k);}protected function back(?string $E=null):Response{$s=Request::current()->header('referer');return Response::redirect($s?:$E??url('/'));}protected function flash(string $k,string $S):void{Session::flash($k,$S);}protected function validate(Request $b,array $K,?string $f=null):?Response{$C=Validator::make($b->all(),$K);if($C->fails()){$i=$b->all();unset($i['password'],$i['password_confirmation'],$i['_csrf'],$i['current_password']);Session::set('_errors',$C->errors());Session::set('_old',$i);Session::flash('error',$C->first()??t('error.validation'));return $this->back($f);}return null;}protected function user():array{return Auth::user()??[];}protected function pageNumber(Request $b):int{return max(1,$b->int('page',1));}}